import java.util.Scanner;

public class Main {
    public static int cntRes(int n) {
        int[] d = new int[n + 1];
        d[0] = 1;
        int s = 0;
        for (int i = 0; i < n; i++) {
            d[i + 1] = d[i] * 2;
        }
        for (int i = 0; i <= n; i++) {
            s += d[i];
        }
        return s;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h = sc.nextInt();
        int n = sc.nextInt();

        int answ = 0;
        int l = 1;
        int r = (int)Math.pow(2, h);
        int b = h;
        String dir = "L";

        for (int i = 0; i < h; i++) {
            if (dir.equals("L")) {
                if (n > (l + r) / 2.0) {
                    answ += cntRes(b) + 1;
                    l = ((l + r) / 2) + 1;
                } else if (n < (l + r) / 2.0) {
                    r = ((l + r) / 2) + (int)((l + r) % 2 != 0) - 1;
                    answ += 1;
                    dir = "R";
                }
                b -= 1;
            } else {
                if (n < (l + r) / 2.0) {
                    answ += cntRes(b) + 1;
                    r = ((l + r) / 2) + (int)((l + r) % 2 != 0) - 1;
                } else if (n > (l + r) / 2.0) {
                    answ += 1;
                    l = ((l + r) / 2) + 1;
                    dir = "L";
                }
                b -= 1;
            }
        }
        System.out.println(answ);
        sc.close();
    }
}

